<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/ActingResumeService.php';

final class ActingResumeExperience
{
    private const ROUTE='/theatre-history/resume';
    public static function handles(string $route):bool{return $route===self::ROUTE;}
    public static function render(string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$viewer=Auth::currentUser($db);if(!$viewer)self::redirect($basePath.'/login');$subjects=StudentProfileService::subjectsForViewer($db,$viewer);$studentId=filter_input(INPUT_GET,'student',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'student_id',FILTER_VALIDATE_INT)?:0;if($studentId<1&&$subjects)$studentId=(int)$subjects[0]['id'];if($studentId<1||!StudentProfileService::canEdit($db,$viewer,(int)$studentId)){http_response_code(404);exit('Acting résumé unavailable.');}$_SESSION['acting_resume_csrf']??=bin2hex(random_bytes(24));if($_SERVER['REQUEST_METHOD']==='POST')self::post($db,$basePath,$viewer,(int)$studentId);$data=ActingResumeService::build($db,$viewer,(int)$studentId);self::page($basePath,$viewer,$subjects,$data,isset($_GET['print']));
    }
    private static function post(PDO $db,string $basePath,array $viewer,int $studentId):never
    {
        if(!hash_equals((string)($_SESSION['acting_resume_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired.');self::redirect($basePath.self::ROUTE.'?student='.$studentId);}try{$action=(string)($_POST['action']??'');if($action==='add_external'){ActingResumeService::saveExternal($db,$viewer,$studentId,$_POST);self::flash('success','External credit added as self-reported.');}elseif($action==='archive_external'){$creditId=filter_input(INPUT_POST,'credit_id',FILTER_VALIDATE_INT)?:0;ActingResumeService::archiveExternal($db,$viewer,$studentId,(int)$creditId);self::flash('success','External credit removed from the active résumé.');}else throw new RuntimeException('Choose a valid résumé action.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}self::redirect($basePath.self::ROUTE.'?student='.$studentId);
    }
    private static function page(string $basePath,array $viewer,array $subjects,array $data,bool $print):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$p=$data['profile'];$name=$p['preferred_name']?:$p['legal_name'];$flash=self::takeFlash();header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e((string)$name)?> · Acting Résumé</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/acting-resume.css')?>"></head><body class="app-body<?=$print?' resume-print':''?>"><div class="unified-shell"><?php if(!$print)AppNavigation::renderSidebar(self::ROUTE,$basePath,$viewer);?><main class="unified-main"><?php if(!$print)AppNavigation::renderHeader('Theatre History','Acting Résumé',$basePath,[['label'=>'Theatre History','href'=>'/theatre-history?student='.(int)$p['id'],'active'=>false],['label'=>'Profile','href'=>'/student-profile?student='.(int)$p['id'],'active'=>false],['label'=>'Résumé','href'=>self::ROUTE.'?student='.(int)$p['id'],'active'=>true]]);?><div class="resume-page"><?php if(!$print&&$flash):?><div class="resume-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><?php if(!$print&&count($subjects)>1):?><nav class="resume-subjects"><?php foreach($subjects as $s):?><a class="<?=((int)$s['id']===(int)$p['id'])?'active':''?>" href="<?=$u(self::ROUTE.'?student='.(int)$s['id'])?>"><?=$e((string)$s['name'])?></a><?php endforeach;?></nav><?php endif;?><?php if(!$print):?><section class="resume-tools"><div><small>RÉSUMÉ BUILDER</small><h2>Verified CTSMD credits + clearly labeled outside experience.</h2><p>External credits remain self-reported and are never displayed as CTSMD verified.</p></div><a class="button" target="_blank" href="<?=$u(self::ROUTE.'?student='.(int)$p['id'].'&print=1')?>">Print / Save PDF</a></section><?php endif;?><article class="resume-sheet"><header><div><h1><?=$e((string)$name)?></h1><p><?=$p['short_bio']?$e((string)$p['short_bio']):'Student performer · Children’s Theatre of Southern Maryland'?></p></div><?php if($p['headshot_stored_file_id']):?><img src="<?=$u('/student-profile/headshot?student='.(int)$p['id'])?>" alt="<?=$e((string)$name)?> headshot"><?php endif;?></header><section><h2>Performance Experience</h2><?php foreach($data['verified'] as $credit):?><div class="resume-credit"><b><?=$e((string)$credit['production_title'])?></b><span><?=$e((string)($credit['role_title']?:'Production participant'))?></span><em>Children’s Theatre of Southern Maryland · <?=$e((string)($credit['season_label']?:''))?></em><small>CTSMD VERIFIED</small></div><?php endforeach;?><?php foreach(array_filter($data['external'],static fn(array $c):bool=>$c['credit_type']==='performance') as $credit):?><div class="resume-credit external"><b><?=$e((string)$credit['production_title'])?></b><span><?=$e((string)($credit['role_title']?:'Participant'))?></span><em><?=$e((string)$credit['organization_name'])?><?=$credit['season_label']?' · '.$e((string)$credit['season_label']):''?></em><small>SELF-REPORTED</small></div><?php endforeach;?><?php if(!$data['verified']&&!array_filter($data['external'],static fn(array $c):bool=>$c['credit_type']==='performance')):?><p class="resume-empty">No performance credits yet.</p><?php endif;?></section><?php $training=array_values(array_filter($data['external'],static fn(array $c):bool=>$c['credit_type']==='training'));if($training):?><section><h2>Training</h2><?php foreach($training as $credit):?><div class="resume-credit external"><b><?=$e((string)$credit['production_title'])?></b><span><?=$e((string)($credit['role_title']?:''))?></span><em><?=$e((string)$credit['organization_name'])?></em><small>SELF-REPORTED</small></div><?php endforeach;?></section><?php endif;?><?php if($p['special_skills']):?><section><h2>Special Skills</h2><p><?=$e((string)$p['special_skills'])?></p></section><?php endif;?></article><?php if(!$print):?><div class="resume-builder-grid"><section class="resume-panel"><small>OUTSIDE EXPERIENCE</small><h3>Add self-reported credit</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['acting_resume_csrf'])?>"><input type="hidden" name="student_id" value="<?=(int)$p['id']?>"><input type="hidden" name="action" value="add_external"><label>Type<select name="credit_type"><option value="performance">Performance</option><option value="crew">Crew / production</option><option value="training">Training</option></select></label><label>Production / training title<input name="production_title" maxlength="190" required></label><label>Role / focus<input name="role_title" maxlength="190"></label><label>Organization<input name="organization_name" maxlength="190" required></label><label>Season / year<input name="season_label" maxlength="100"></label><label>Notes<input name="notes" maxlength="500"></label><button class="button" type="submit">Add external credit</button></form></section><section class="resume-panel"><small>SELF-REPORTED CREDITS</small><h3>Manage outside experience</h3><?php if(!$data['external']):?><p>No external credits.</p><?php endif;?><?php foreach($data['external'] as $credit):?><div class="resume-manage"><span><b><?=$e((string)$credit['production_title'])?></b><small><?=$e((string)$credit['organization_name'])?> · <?=$e(ucfirst((string)$credit['credit_type']))?></small></span><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['acting_resume_csrf'])?>"><input type="hidden" name="student_id" value="<?=(int)$p['id']?>"><input type="hidden" name="credit_id" value="<?=(int)$credit['id']?>"><button name="action" value="archive_external" type="submit">Remove</button></form></div><?php endforeach;?></section></div><?php else:?><footer class="resume-verification">CTSMD-verified credits are drawn from Children’s Theatre of Southern Maryland production records. External credits are self-reported.</footer><script>window.addEventListener('load',()=>window.print());</script><?php endif;?></div></main></div><?php if(!$print):?><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script><script>(()=>{if(window.innerWidth>780)return;const header=document.querySelector('.unified-header');if(!header||header.querySelector('.native-back'))return;const back=document.createElement('a');back.className='native-back';back.href='<?=$u('/theatre-history?student='.(int)$p['id'])?>';back.setAttribute('aria-label','Back to Theatre History');back.textContent='‹';header.appendChild(back);})();</script><?php endif;?></body></html><?php exit;
    }
    private static function flash(string $type,string $message):void{$_SESSION['acting_resume_flash']=['type'=>$type,'message'=>$message];}private static function takeFlash():?array{$v=$_SESSION['acting_resume_flash']??null;unset($_SESSION['acting_resume_flash']);return is_array($v)?$v:null;}private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
